with with_windows as (select *, first_value(cost, true) over (order by delivered_date, id rows between unbounded preceding and current row) as first_known_cost, round(cost / sum(cost) over (partition by order_id), 4) as cost_share from shipments where year(delivered_date) = 2023), with_windows_shipments as (select id, carrier, shipped_date, delivered_date, cost, status, first_known_cost, ntile(4) over (order by cost_share desc, id) as cost_share_bucket, sum(first_known_cost) over (partition by carrier, order_id order by delivered_date, id rows between unbounded preceding and current row) as running_first_known_cost from with_windows), ranked as (select *, row_number() over (partition by carrier order by first_known_cost nulls last, id) as row_num from with_windows_shipments qualify row_num = 1), valid as (select *, round(row_num * 1.1, 2) as adjusted_row_num from ranked where shipped_date > date '2023-08-06' and carrier is distinct from 'FedEx'), daily as (select date_trunc('quarter', shipped_date) as quarter_start, sort_array(collect_set(status)) as status_list, sum(case when status = 'DELIVERED' then adjusted_row_num else 0 end) as delivered_adjusted_row_num from valid group by date_trunc('quarter', shipped_date)) select quarter_start, status_list, delivered_adjusted_row_num from daily;
